declare(strict_types=1);require_once __DIR__.'/includes/functions.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('profile.php');verify_csrf();$id=(int)($_POST['id']??0);$stmt=db()->prepare('SELECT author_id,title FROM recipes WHERE id=?');$stmt->execute([$id]);$r=$stmt->fetch();if(!$r||((int)$r['author_id']!==(int)current_user()['id']&&!is_admin())){http_response_code(403);exit('Not allowed.');}db()->prepare('DELETE FROM recipes WHERE id=?')->execute([$id]);audit('RECIPE_DELETE',$id,$r['title']);flash('success','Recipe deleted.');redirect(is_admin()?'admin/recipes.php':'profile.php');
